<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue';
import {
  getThemeMode,
  setThemeMode,
  getCurrentTheme,
  onThemeChange,
  setThemeShortcuts,
  getThemeShortcuts,
  type ThemeMode
} from '../../../utils/theme';
import {
  themePresets,
  applyThemePreset,
  resetToDefaultTheme,
  getThemePresets
} from '../../../utils/theme-presets';

const isOpen = ref(false);
const currentMode = ref<ThemeMode>('light');
const currentPreset = ref<string>('default');
const isDark = ref(false);
const systemPrefersDark = ref(false);

// 预设列表
const presets = computed(() => {
  return getThemePresets(isDark.value);
});

// 显示的 CSS 变量
const displayVariables = computed(() => {
  const root = document.documentElement;
  const style = getComputedStyle(root);
  const variables = [
    '--el-color-primary',
    '--el-color-success',
    '--el-color-warning',
    '--el-color-danger',
    '--el-bg-color',
    '--el-bg-color-page',
    '--el-text-color-primary',
    '--el-border-color'
  ];

  const result = {};
  variables.forEach(name => {
    result[name] = style.getPropertyValue(name).trim();
  });
  return result;
});

// 切换调试器
const toggleDebugger = () => {
  isOpen.value = !isOpen.value;
};

// 设置主题
const setTheme = (mode: ThemeMode) => {
  setThemeMode(mode);
};

// 应用预设
const applyPreset = (presetName: string) => {
  applyThemePreset(presetName, isDark.value);
  currentPreset.value = presetName;
};

// 重置主题
const resetTheme = () => {
  resetToDefaultTheme(isDark.value);
  currentPreset.value = 'default';
};

// 复制变量
const copyVariables = () => {
  const vars = displayVariables.value;
  const text = Object.entries(vars)
    .map(([name, value]) => `${name}: ${value};`)
    .join('\n');

  navigator.clipboard.writeText(text).then(() => {
    alert('CSS 变量已复制到剪贴板！');
  });
};

// 导出主题
const exportTheme = () => {
  const theme = {
    mode: currentMode.value,
    preset: currentPreset.value,
    variables: displayVariables.value,
    isDark: isDark.value
  };

  const blob = new Blob([JSON.stringify(theme, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `theme-${Date.now()}.json`;
  a.click();
  URL.revokeObjectURL(url);
};

// 更新状态
const updateState = () => {
  currentMode.value = getThemeMode();
  isDark.value = getCurrentTheme() === 'dark';
  systemPrefersDark.value = window.matchMedia('(prefers-color-scheme: dark)').matches;
};

onMounted(() => {
  updateState();

  const unsubscribe = onThemeChange(updateState);

  // 监听系统主题变化
  const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
  mediaQuery.addEventListener('change', updateState);

  onUnmounted(() => {
    unsubscribe();
    mediaQuery.removeEventListener('change', updateState);
  });
});
</script>

