import { ref, onMounted, onUnmounted, computed } from 'vue';
import { NovaThemeSwitch } from '@nova-cbb/nova-ui';
import { 
  initTheme, 
  getThemeMode, 
  getCurrentTheme, 
  onThemeChange,
  type ThemeMode 
} from '../../../src/utils/theme';
import {
  themePresets,
  applyThemePreset,
  getThemePresets
} from '../../../src/utils/theme-presets';

const themeMode = ref<ThemeMode>('light');
const isDark = ref(false);
const currentPreset = ref('默认');

// 预设列表
const lightPresets = computed(() => {
  return getThemePresets(false);
});

const darkPresets = computed(() => {
  return getThemePresets(true);
});

// 获取预设颜色
const presetColors = (preset) => {
  return [
    preset.colors.primary,
    preset.colors.success,
    preset.colors.warning,
    preset.colors.danger
  ];
};

// 应用预设
const applyPreset = (presetName, dark = false) => {
  applyThemePreset(presetName, dark);
  currentPreset.value = presetName;

  // 如果是暗色预设，切换到暗色模式
  if (dark) {
    // 使用自定义函数设置暗色主题
    localStorage.setItem('nova-ui-theme', 'dark');
    document.documentElement.setAttribute('data-theme', 'dark');
    isDark.value = true;
  } else {
    localStorage.setItem('nova-ui-theme', 'light');
    document.documentElement.setAttribute('data-theme', 'light');
    isDark.value = false;
  }
};

// 更新状态
const updateState = () => {
  themeMode.value = getThemeMode();
  isDark.value = getCurrentTheme() === 'dark';
};

onMounted(() => {
  initTheme();
  updateState();

  const unsubscribe = onThemeChange(updateState);

  onUnmounted(unsubscribe);
});
</script>

